// ==== auditoria_categorias.js ====
// static/js/modules/pasta_categorias/acoes_e_modais/pasta_auditoria/auditoria_categorias.js
// ==========================================================
// AUDITORIA DE CATEGORIAS — Modal accordion
// ==========================================================

(function() {
    'use strict';

    if (!window.fecharModalAuditoria) {
        window.fecharModalAuditoria = function() {
            var container = document.getElementById('modal-auditoria-container');
            if (container) container.innerHTML = '';
            document.body.style.overflow = '';
        };
    }

    if (!window.toggleAuditEntry) {
        window.toggleAuditEntry = function(headerEl) {
            var entry = headerEl.closest('.audit-entry');
            if (!entry) return;
            entry.classList.toggle('open');
        };
    }

    document.body.addEventListener('htmx:afterSwap', function(evt) {
        if (evt.detail.target && evt.detail.target.id === 'modal-auditoria-container') {
            var modal = document.getElementById('modalAuditoria');
            if (modal) {
                modal.onclick = function(e) {
                    if (e.target === modal) window.fecharModalAuditoria();
                };
                var primeiro = modal.querySelector('.audit-entry');
                if (primeiro) primeiro.classList.add('open');
            }
            document.body.style.overflow = 'hidden';
        }
    });

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            var modal = document.getElementById('modalAuditoria');
            if (modal) window.fecharModalAuditoria();
        }
    });

    console.log('✅ Sistema de auditoria de categorias carregado!');
})();

// ==== categorias.js ====
// static/js/modules/pasta_categorias/categorias.js
// ==========================================================
// ORQUESTRADOR - CATEGORIAS
// ==========================================================

(function() {
    'use strict';

    function recarregarTabelaCategorias() {
        var tabelaContainer = document.getElementById('tabela-container');
        if (!tabelaContainer) return;
        var urlRefresh = tabelaContainer.dataset.urlRefresh || '/categorias/';
        if (window.htmx) {
            window.htmx.ajax('GET', urlRefresh, {
                target: '#tabela-container',
                swap: 'outerHTML',
                headers: { 'HX-Request': 'true' }
            });
        }
    }

    function init() {
        document.body.addEventListener('atualizarTabelaCategorias', function() {
            recarregarTabelaCategorias();
        });
    }

    window.recarregarTabelaCategorias = recarregarTabelaCategorias;

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    console.log('✅ CATEGORIAS - MAIN carregado!');
})();

